double MiscEngine::result() const {
    if (isColor()) {
        return 0.0;
    }

    if (isCurrency()) {
        const auto &list = currencies();
        if (m_fromIndex < 0 || m_fromIndex >= list.size() ||
            m_toIndex < 0 || m_toIndex >= list.size()) {
            return 0.0;
        }
        const double fromRate = rateFor(list[m_fromIndex].code);
        const double toRate = rateFor(list[m_toIndex].code);
        if (fromRate <= 0.0) {
            return 0.0;
        }
        return m_amount * toRate / fromRate;
    }

    const auto &units = currentUnits();
    if (m_fromIndex < 0 || m_fromIndex >= units.size() ||
        m_toIndex < 0 || m_toIndex >= units.size()) {
        return 0.0;
    }

    return m_amount * units[m_fromIndex].factor / units[m_toIndex].factor;
}

QString MiscEngine::resultText() const {
    if (isColor()) {
        return hex();
    }
    return formatValue(result());
}

QString MiscEngine::conversionText() const {
    if (isColor()) {
        return tr("RGB(%1, %2, %3)")
            .arg(m_color.red())
            .arg(m_color.green())
            .arg(m_color.blue());
    }

    if (isCurrency()) {
        const auto &list = currencies();
        if (m_fromIndex < 0 || m_fromIndex >= list.size() ||
            m_toIndex < 0 || m_toIndex >= list.size()) {
            return {};
        }
        const double fromRate = rateFor(list[m_fromIndex].code);
        if (fromRate <= 0.0) {
            return {};
        }
        const double one = rateFor(list[m_toIndex].code) / fromRate;
        return QStringLiteral("1 %1 = %2 %3")
            .arg(list[m_fromIndex].code, formatValue(one), list[m_toIndex].code);
    }

    const auto &units = currentUnits();
    if (m_fromIndex < 0 || m_fromIndex >= units.size() ||
        m_toIndex < 0 || m_toIndex >= units.size()) {
        return {};
    }
    const double one = units[m_fromIndex].factor / units[m_toIndex].factor;
    return QStringLiteral("1 %1 = %2 %3")
        .arg(units[m_fromIndex].symbol, formatValue(one), units[m_toIndex].symbol);
}

