void MiscEngine::refreshRates() {
    if (m_ratesLoading) {
        return;
    }

    if (!m_network) {
        m_network = new QNetworkAccessManager(this);
    }

    QNetworkRequest request{QUrl(QString::fromLatin1(RatesUrl))};
    request.setTransferTimeout(8000);
    request.setHeader(QNetworkRequest::UserAgentHeader, QStringLiteral("Hisaab/1.0 (Qt)"));

    setRatesLoading(true);
    setRateStatus(tr("Refreshing live rates…"));

    m_reply = m_network->get(request);

    connect(m_reply, &QNetworkReply::finished, this, [this]() {
        QNetworkReply *reply = m_reply;
        m_reply = nullptr;
        if (!reply) {
            return;
        }

        setRatesLoading(false);

        const auto fail = [this, reply](const QString &reason) {
            Q_UNUSED(reason);
            if (m_lastRatesUpdated.isEmpty()) {
                setRateStatus(tr("Offline rates · update failed"));
            } else {
                setRateStatus(tr("Cached rates · update failed"));
            }
            reply->deleteLater();
        };

        if (reply->error() != QNetworkReply::NoError) {
            fail(reply->errorString());
            return;
        }

        QJsonParseError parseError;
        const QJsonDocument document = QJsonDocument::fromJson(reply->readAll(), &parseError);
        if (parseError.error != QJsonParseError::NoError || !document.isObject()) {
            fail(parseError.errorString());
            return;
        }

        const QJsonObject root = document.object();
        if (root.value(QStringLiteral("result")).toString() != QStringLiteral("success")) {
            fail(root.value(QStringLiteral("error-type")).toString());
            return;
        }

        const QJsonObject ratesObject = root.value(QStringLiteral("rates")).toObject();
        QVariantMap rates;
        for (auto it = ratesObject.constBegin(); it != ratesObject.constEnd(); ++it) {
            const double value = it.value().toDouble();
            if (value > 0.0) {
                rates.insert(it.key(), value);
            }
        }

        if (rates.isEmpty()) {
            fail(QStringLiteral("empty rates"));
            return;
        }
        rates.insert(QStringLiteral("USD"), 1.0);

        m_rates = rates;

        QString updated = root.value(QStringLiteral("time_last_update_utc")).toString().trimmed();
        if (updated.isEmpty()) {
            updated = QDateTime::currentDateTimeUtc().toString(Qt::ISODate);
        }
        m_lastRatesUpdated = updated;

        QSettings settings(QStringLiteral("Noctalia"), QStringLiteral("hisaab"));
        settings.setValue(QString::fromLatin1(RatesCacheKey), m_rates);
        settings.setValue(QString::fromLatin1(RatesUpdatedKey), m_lastRatesUpdated);
        settings.sync();

        setRateStatus(tr("Live rates · %1").arg(updated));
        Q_EMIT resultChanged();

        reply->deleteLater();
    });
}

void MiscEngine::setHex(const QString &hex) {
    QString text = hex.trimmed();
    if (text.isEmpty()) {
        return;
    }
    if (!text.startsWith(QLatin1Char('#'))) {
        text.prepend(QLatin1Char('#'));
    }

    QColor parsed(text);
    if (!parsed.isValid() && text.size() == 7) {
        // Accept shorthand-style input without a leading hash.
        parsed = QColor(text);
    }
    if (parsed.isValid()) {
        setColor(parsed);
    }
}

void MiscEngine::setRgb(int red, int green, int blue) {
    setColor(QColor(qBound(0, red, 255),
                    qBound(0, green, 255),
                    qBound(0, blue, 255)));
}

void MiscEngine::setRed(int red) {
    setRgb(red, m_color.green(), m_color.blue());
}

void MiscEngine::setGreen(int green) {
    setRgb(m_color.red(), green, m_color.blue());
}

void MiscEngine::setBlue(int blue) {
    setRgb(m_color.red(), m_color.green(), blue);
}

void MiscEngine::setColor(const QColor &color) {
    if (!color.isValid()) {
        return;
    }

    QColor opaque(color.red(), color.green(), color.blue());
    if (m_color.rgb() == opaque.rgb()) {
        return;
    }

    m_color = opaque;
    Q_EMIT colorChanged();
}

