QPair<int, int> MiscEngine::defaultIndices(int category) {
    switch (category) {
    case CurrencyCategory:
        return {0, 3};   // USD -> INR
    case MassCategory:
        return {0, 4};   // kg -> lb
    case LengthCategory:
        return {0, 6};   // m -> ft
    case DataCategory:
        return {3, 4};   // MB -> GB
    case SpeedCategory:
        return {1, 2};   // km/h -> mph
    case ColorCategory:
    default:
        return {0, 0};
    }
}

QString MiscEngine::formatValue(double value) {
    return QString::fromStdString(MathParser::formatNumber(value, 6));
}

const QVector<MiscEngine::Unit> &MiscEngine::currentUnits() const {
    static const QVector<Unit> empty;
    switch (m_category) {
    case MassCategory:
        return massUnits();
    case LengthCategory:
        return lengthUnits();
    case DataCategory:
        return dataUnits();
    case SpeedCategory:
        return speedUnits();
    default:
        return empty;
    }
}

double MiscEngine::rateFor(const QString &code) const {
    const double rate = m_rates.value(code, 0.0).toDouble();
    if (rate > 0.0) {
        return rate;
    }
    return fallbackRates().value(code, 1.0).toDouble();
}

void MiscEngine::setRatesLoading(bool loading) {
    if (m_ratesLoading == loading) {
        return;
    }
    m_ratesLoading = loading;
    Q_EMIT ratesLoadingChanged();
}

void MiscEngine::setRateStatus(const QString &status) {
    if (m_rateStatus == status) {
        return;
    }
    m_rateStatus = status;
    Q_EMIT rateStatusChanged();
}

void MiscEngine::loadCachedRates() {
    QSettings settings(QStringLiteral("Noctalia"), QStringLiteral("hisaab"));
    const QVariantMap cached = settings.value(QString::fromLatin1(RatesCacheKey)).toMap();

    if (!cached.isEmpty()) {
        m_rates = cached;
        m_rates.insert(QStringLiteral("USD"), 1.0);
        m_lastRatesUpdated = settings.value(QString::fromLatin1(RatesUpdatedKey)).toString();
        if (m_lastRatesUpdated.isEmpty()) {
            m_rateStatus = tr("Cached rates");
        } else {
            m_rateStatus = tr("Cached rates · %1").arg(m_lastRatesUpdated);
        }
        return;
    }

    m_rates = fallbackRates();
    m_rateStatus = tr("Offline rates");
}

